class Solution:
    def colourVertices(self, n: int, edges: List[List[int]]) -> List[int]:
        adj = [[] for _ in range(n + 1)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        col = [0] * (n + 1)
        for v in range(1, n + 1):
            used = {col[u] for u in adj[v]}
            c = 1
            while c in used: c += 1
            col[v] = c
        return col[1:]

